fn format_g(f: f64) -> String {
    if f == 0.0 { return "0".to_string(); }
    let p = 6; // significant digits
    // Get exponent via format {:.5e} which rounds mantissa to 6 sig digits
    let s = format!("{:.*e}", p - 1, f); // e.g. "8.98438e-1"
    // parse mantissa and exp
    let epos = s.find('e').unwrap();
    let exp: i32 = s[epos+1..].parse().unwrap();
    let mantissa = &s[..epos]; // "d.ddddd" possibly with '-' 
    if exp < -4 || exp >= p as i32 {
        // scientific: strip trailing zeros in mantissa
        let m = mantissa.trim_end_matches('0').trim_end_matches('.');
        format!("{}e{}{:02}", m, if exp < 0 { "-" } else { "+" }, exp.abs())
    } else {
        // fixed with precision p-1-exp
        let prec = (p as i32 - 1 - exp) as usize;
        let fixed = format!("{:.*}", prec, f);
        // strip trailing zeros and possibly trailing dot
        let t = fixed.trim_end_matches('0').trim_end_matches('.');
        t.to_string()
    }
}
```

